'use strict';

const { runCommand } = require('./_api_runner.cjs');

const OPTION_SPECS = [
  {
    "type": "boolean_flag",
    "flag": "--help",
    "keys": [
      "help"
    ]
  },
  {
    "type": "boolean_flag",
    "flag": "--verbose",
    "keys": [
      "verbose"
    ]
  },
  {
    "type": "value",
    "flag": "--timeout",
    "keys": [
      "timeout"
    ]
  },
  {
    "type": "value",
    "flag": "--app_access_token",
    "keys": [
      "app_access_token",
      "appAccessToken"
    ]
  },
  {
    "type": "repeatable_value",
    "flag": "--header",
    "keys": [
      "header",
      "headers",
      "extraHeaders"
    ]
  }
];

async function runMoaFeatureProbe(params = {}, runtimeOptions = {}) {
  return runCommand({
    scriptRelativePath: 'scripts/moa_feature_probe.js',
    params,
    optionSpecs: OPTION_SPECS,
    runtimeOptions,
  });
}

module.exports = {
  runMoaFeatureProbe,
};
module.exports.default = runMoaFeatureProbe;
